    "id": "fresh-XbXxeOb9OhI",
    "title": "Leverage AI to Ship Big Tech Products with Ethan Evans (fmr Amazon VP) & David Markley (Tech VP)",
    "deck": "A new public video from Ethan Evans.",
    "topic": "ai-product-leadership",
    "topicLabel": "AI-Era Work & Product Leadership",
