    "id": "fresh-uO0dI_tCvUU",
    "title": "Be a High-Value Connector & Networker with Andrew Yeung (Founder & Investor; ex-Google; ex-Meta)",
    "deck": "A new public video from Ethan Evans.",
    "topic": "career-transitions",
    "topicLabel": "Career Transitions & Independent Work",
